"""Fill the remaining A+ branches with original technical and operational chapters."""
import importlib.util,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('aplus_base',root/'scripts/build-aplus-depth.py')
base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
lessons=base.lessons
def add(topic,key,title,text,terms,diagram,q1,a1,b1,c1,e1,q2,a2,b2,c2,e2,lab,related=None):
 lessons.append(dict(topic=topic,key=key,title=title,explanation=text,distinctions=[f'{term}: {meaning}' for term,meaning in terms],reference=[dict(term=t,meaning=m) for t,m in terms],example=dict(situation=q1,reasoning=e1,result=a1),diagram=diagram,lab=lab,related=related or [],questions=[dict(id=f'depth:{key}:1',prompt=q1,options=[a1,b1,c1],answer=0,explanation=e1,tier=3),dict(id=f'depth:{key}:2',prompt=q2,options=[a2,b2,c2],answer=0,explanation=e2,tier=3)],sources=[dict(title=title,url=url) for title,url in ([base.MS,base.CMD] if topic.startswith('core2') else [base.MS,('IEEE Ethernet references','https://www.ieee802.org/3/')])]))

add('core1-2.3','host-service-roles','Host services, internet appliances and constrained devices',
 'A server role describes a service, not necessarily a dedicated physical computer. One host can run several services, and one service can span many hosts. DNS answers name queries, DHCP leases configuration, a file server shares stored resources, a print server queues jobs, and a mail server handles defined mail functions. A database service stores and retrieves structured application data under its own access model. Syslog transports event messages; NTP supports time synchronization. AAA separates authentication, authorization and accounting, which can be provided through coordinated services. A proxy mediates selected requests, a load balancer distributes traffic, and a spam gateway evaluates mail. UTM products combine functions but still need correct policy. Legacy and embedded devices, including SCADA and IoT systems, may have unusual uptime, safety, patching and vendor-support constraints. Do not apply a disruptive desktop repair to an industrial device without understanding its process role and authorized maintenance procedure.',
 [('Server role','A service function can be virtual, distributed or combined with others.'),('Syslog/NTP','Event transport and time synchronization are separate operational dependencies.'),('Proxy/load balancer','Mediation versus distribution of requests.'),('SCADA/IoT','Operational and embedded devices may require specialized safety and maintenance handling.')],['Client request','Service identity and protocol','Application/data dependency','Verified response'],
 'An application reaches its database by IP but fails when using the configured name. Which service boundary is most relevant?', 'Name resolution and the configured DNS record/resolver', 'Replace every database disk immediately', 'Assume successful IP access proves DNS is correct', 'Separate name resolution from database reachability and application authentication.',
 'A technician wants to reboot an unfamiliar industrial controller during business operations. What should happen first?', 'Identify its process role and follow the authorized vendor/operations maintenance process', 'Treat it exactly like a personal laptop without consultation', 'Disable all logging before rebooting', 'A controller can affect a physical process; scope and operational authority matter.',
 ['Draw five service roles and their dependencies without assigning one box per role automatically.','Compare proxy and load-balancer decisions for one web request.','Write an escalation plan for an embedded device with unknown operational impact.'])

add('core1-2.6','soho-baseline','A complete small-office connection and security baseline',
 'Set up a small-office network by separating physical connectivity, addressing, wireless configuration, management access and security policy. Identify the provider handoff and router WAN configuration before assuming a private LAN address belongs on the external interface. Define the LAN subnet, DHCP pool, exclusions or reservations and appropriate DNS options without overlap. Configure a supported wireless security mode, an intentional channel plan and guest isolation. Changing or hiding an SSID does not establish confidentiality or access control. Replace default management credentials and restrict administration to an approved path. Port forwarding deliberately exposes a service through a boundary and must match a documented need, target, transport and port. Review automatic port-mapping behavior rather than enabling every convenience feature by default. Maintain supported firmware and a protected configuration backup. Verify both an authorized successful flow and an unauthorized denied flow; a single working web page does not prove segmentation or management security.',
 [('WAN/LAN','Provider-facing and internal addressing contexts can differ.'),('DHCP design','Avoid overlap between dynamic allocation and static assignments.'),('Guest access','A separate SSID needs actual traffic policy to isolate resources.'),('Port forwarding','A scoped exposure, not a universal fix for application problems.')],['Provider/WAN','Router/firewall boundary','LAN/DHCP/DNS','Wireless and guest policy'],
 'Guests use a different SSID but can open payroll shares. What is missing?', 'Effective network separation and access rules, tested from a guest client', 'Only a longer SSID name', 'A different wallpaper on office computers', 'Names are not enforcement boundaries; verify the actual traffic policy.',
 'A user asks to forward every port to a workstation to fix one app. What is the appropriate approach?', 'Identify the required service and approve the narrowest justified exposure', 'Forward all traffic permanently without investigation', 'Assume every connection failure is caused by the router', 'A broad exposure adds unnecessary risk and can conceal the actual fault.',
 ['Build a subnet/pool/reservation table.','Draw authorized and guest paths to a shared resource.','Define one required inbound rule and one forbidden management path.'])

add('core1-2.7','connection-scope','WAN media, network scopes and realistic failover',
 'Compare access options using the application’s bandwidth, latency, jitter, reliability, coverage and usage requirements. Fiber and cable can provide high capacity but have provider and physical-path dependencies. DSL depends on the relevant copper service and distance characteristics. Cellular performance varies with coverage, congestion, plan and antenna conditions. Satellite services differ in orbit and design, so avoid one universal latency claim; verify the actual offering. A WISP supplies wireless internet access through its deployment model. Distinguish a LAN from a WAN, a WLAN from any wireless technology, a PAN for nearby personal devices, a MAN across a metropolitan scope and a SAN designed for storage communication. These labels describe scope or function, not automatic security guarantees. A backup link is useful only if routing/failover, capacity and dependencies are tested; two subscriptions can still share the same conduit, power or upstream equipment.',
 [('PAN/LAN/WLAN','Personal, local and wireless-local scopes differ.'),('MAN/WAN','Metropolitan and broader network scopes.'),('SAN','Storage-oriented networking, not merely any shared folder.'),('Failover diversity','Check actual physical, provider and power independence.')],['Required application behavior','Available media/provider','Shared failure dependencies','Tested backup capacity'],
 'Two internet links enter through the same damaged conduit. What does the outage show?', 'Logical redundancy did not remove the shared physical dependency', 'Two service contracts guarantee path independence', 'DNS is always the cause of all dual-link outages', 'Assess the actual infrastructure path rather than counting subscriptions.',
 'A branch uses cloud voice calls over a backup link. Which checks matter beyond download speed?', 'Latency, jitter, loss, uplink capacity, coverage and failover behavior', 'Only the monthly advertising slogan', 'Only the connector color', 'Real-time application behavior depends on timing and the complete path.',
 ['Compare four hypothetical WAN offers with explicit assumptions.','Draw shared and independent failure paths.','Plan a backup-link test while protecting ongoing work.'])

add('core1-2.8','network-tools-decision','Choosing installation and diagnostic tools by evidence',
 'Use a tool whose measurement answers the current question. A crimper terminates compatible plugs, while a punchdown tool seats conductors into suitable insulation-displacement terminations. A stripper removes an appropriate jacket or insulation without damaging conductors. A tone generator and probe help trace a run but do not certify its bandwidth. A basic cable tester can expose continuity or wire-map problems; a more capable certification instrument checks specified performance characteristics. A loopback can help isolate a supported port or path under the device’s test procedure. A network tap or mirrored port can provide traffic for an authorized packet analysis, but its placement, direction and capture limits affect what is visible. A Wi-Fi analyzer provides radio/network observations, not proof that an application login works. Record tool model, configuration, test point and limitations so another technician can interpret the result.',
 [('Crimp/punchdown/strip','Different termination and preparation operations.'),('Tone versus test','Tracing a run differs from testing its wiring or performance.'),('Tap/mirror/capture','Observation path and loss constraints affect evidence.'),('Wi-Fi analyzer','Radio evidence is separate from IP/application success.')],['Question','Correct tool and test point','Observed result','Known limitations'],
 'A tone probe locates a cable. Does that establish it meets the required Ethernet performance?', 'No; use the appropriate wiring/performance test for the installation', 'Yes, audibility proves the full bandwidth rating', 'Yes, location establishes every pair is correctly terminated', 'Cable tracing identifies a path, not its complete electrical performance.',
 'An authorized capture contains no server responses. What should be checked before concluding the server sent nothing?', 'Capture location, direction, filter and visibility limits', 'Only the analyst’s desktop theme', 'Assume every tap shows every packet on the entire network', 'A capture is evidence from a particular observation point and configuration.',
 ['Map six support questions to tool categories.','Describe a correct wire-map test point.','Record capture scope and privacy controls for a fictional troubleshooting case.'])

add('core1-5.1','hardware-fault-tree','No power, no POST, thermal shutdown and intermittent faults',
 'Classify the starting state before replacing parts. No power, power with no POST, firmware success with no OS and a crash after login are different boundaries. Check the external power path and documented controls without opening hazardous components. Fans or LEDs do not prove that all required rails, connectors or firmware initialization stages work. Vendor POST beeps, diagnostic LEDs and documented crash indicators can narrow a hypothesis but must be interpreted for the exact model. Repeated shutdown under load with high temperatures suggests a cooling or power investigation; a burning smell warrants stopping and following safe escalation rather than repeated restart attempts. Sluggish performance can result from CPU load, memory pressure, storage, heat or software, so observe the trigger. Record recent changes, reseat compatible components only with power safely isolated, test one theory at a time and verify under the original workload.',
 [('No power/no POST/no OS','Different fault boundaries require different evidence.'),('Thermal throttling/shutdown','Protective behavior can reduce speed or stop operation.'),('POST indicator','Model-specific evidence, not a universal beep dictionary.'),('Intermittent fault','Correlate workload, environment, power and recent changes.')],['External power','Board/CPU/RAM initialization','Firmware boot selection','OS and workload'],
 'Fans spin but there is no firmware display after a RAM change. What is a targeted next investigation?', 'Documented POST indicators and compatible memory seating/population with power isolated', 'Reinstall the browser', 'Format the drive before checking POST', 'The symptom is at hardware initialization, earlier than ordinary application troubleshooting.',
 'A machine emits a burning smell during repeated restart attempts. What should happen?', 'Stop use and follow safe power isolation and service escalation procedures', 'Keep restarting until the smell disappears', 'Disable temperature warnings', 'A possible electrical hazard requires safe handling, not repeated stress.',
 ['Build a four-state startup fault tree.','Map evidence to a narrowly scoped hypothesis.','Define a safe stopping condition and a workload-based verification test.'])

add('core1-5.2','storage-diagnostic-boundary','Degraded arrays, boot order, capacity and failing storage',
 'A storage complaint can mean the device is not detected, a volume is unavailable, an OS cannot boot, space is exhausted or performance is poor. Establish which layer sees the device before applying filesystem repairs. After hardware or firmware changes, check supported controller modes, physical connections and boot order without assuming data was erased. SMART or vendor health warnings can justify urgent data-protection action but do not predict every failure with certainty. A degraded RAID array may remain online while operating with reduced fault tolerance; identify the failed member and use the documented replacement/rebuild procedure. Selecting the wrong member or changing an array blindly can destroy recoverability. Low capacity, high latency, excessive queueing and workload saturation are different metrics. Protect valuable data before stressful tests on a suspected failing device and verify the actual recovery copy rather than relying on a healthy-looking icon.',
 [('Detection/volume/boot','Controller recognition, storage layout and OS boot selection are separate layers.'),('SMART warning','Useful health evidence with limits, not a complete prediction oracle.'),('Degraded RAID','Data may remain accessible while redundancy is reduced.'),('Space/throughput/latency','Capacity and performance measurements are not interchangeable.')],['Device detection','Array/volume state','Boot path','Application I/O behavior'],
 'An array remains readable after a disk failure. What must the technician avoid assuming?', 'That readable data means full redundancy and independent recovery are intact', 'That every array is now a verified backup', 'That the failed member can be chosen by guessing its slot', 'A degraded state and a usable recovery copy are separate issues.',
 'After adding a drive, firmware attempts to boot the wrong device. What is a reasonable check?', 'The documented boot order and intended bootloader path before destructive repair', 'Erase all drives immediately', 'Replace the monitor', 'Boot selection errors can occur while the original data remains intact.',
 ['Draw detection, array, volume and boot boundaries.','Write a hypothetical degraded-array service checklist with member verification.','Define data-protection and stopping criteria before tests.'])

add('core1-5.3','display-fault-tree','Display/projector symptoms and isolation tests',
 'Separate no power, no input signal, a visible-but-dim image, distorted output and application-only rendering errors. A display’s own menu or self-test can establish some local operation without proving the host signal path. Check the selected input, known-good supported cable/adapter and source output mode before replacing a panel. An image visible under appropriate inspection on an older backlit design may suggest a light-path fault, while intermittent artifacts can involve GPU load/temperature, memory, cable bandwidth or the panel. Projectors add lamp or light-source state, focus, keystone, ventilation and supported placement concerns; do not stare into a light source or service hot components casually. Wrong color, overscan, resolution and refresh settings are configuration questions before they are automatically hardware failures. Replicate the original condition and swap one known-good element at a time so the test identifies a boundary.',
 [('Local menu versus input','A self-generated image bypasses part of the external signal path.'),('Dim/blank/distorted','Different symptoms suggest different hypotheses.'),('Projector focus/keystone/ventilation','Optical geometry and thermal factors matter.'),('Known-good path','Supported source, cable, adapter and mode are tested together.')],['Source mode','Cable/adapter/input','Image/light path','Observed output'],
 'A monitor shows its setup menu but reports no signal from one PC. What should be checked next?', 'Selected input and a supported known-good source/cable path', 'Assume the internal menu proves the PC output works', 'Delete the PC’s user files', 'The local menu verifies a different path than the external signal.',
 'A projector shuts down after warming up and its intake is obstructed. What is a fitting investigation?', 'Ventilation and documented thermal/light-source indicators', 'Only the browser bookmarks', 'Keep defeating its protective shutdown', 'Thermal evidence and safe maintenance instructions should guide the response.',
 ['Make a symptom-to-boundary table.','Plan one-component-at-a-time isolation for an artifacting display.','Include safe projector handling and a repeatable output test.'])

add('core1-5.4','mobile-fault-tree','Mobile power, input, liquid damage and intermittent peripherals',
 'Record whether the fault concerns charging, battery runtime, thermal behavior, display, input, radio or an application. A worn battery can lose useful runtime without every case showing visible swelling; physical deformation still changes the response to a safety issue. A device that charges only when a cable is held at an angle suggests a connector or cable path investigation, not an immediate factory reset. Liquid exposure can create delayed corrosion and shorts, so follow the model’s approved service and data-protection route rather than powering it repeatedly to see if it works. Touch, keyboard, camera and microphone problems can also involve permissions, accessibility settings, drivers, firmware or application selection. A working external peripheral can help isolate some internal paths, but does not prove every board component is healthy. Use the exact vendor procedure for parts, adhesive, pairing/calibration and post-service verification.',
 [('Battery wear versus swelling','Runtime degradation and physical hazard are different findings.'),('Charging path','Adapter, cable, port, negotiation and battery can each be involved.'),('Liquid exposure','Stop speculative power cycling; use approved service handling.'),('Input hardware versus settings','Touch and keyboard behavior can have configuration causes.')],['Symptom and recent event','Power/physical state','OS permission/configuration','Scoped service and verification'],
 'A phone becomes unreliable after liquid exposure. Is repeated charging a suitable diagnostic experiment?', 'No; follow the approved isolation/service procedure and protect data', 'Yes, heat from charging is a reliable drying method', 'Yes, an occasional successful boot proves no damage remains', 'Powering a damaged device can worsen faults and does not establish safe recovery.',
 'A microphone works in recordings but not one meeting app. What is a narrow next check?', 'The meeting app’s selected input and microphone permissions', 'Replace the whole battery first', 'Erase the storage before testing permissions', 'Application-specific success and failure help isolate the boundary.',
 ['Draw a charging-path checklist.','Separate hazardous from ordinary service symptoms.','Plan permissions versus hardware tests for an input device.'])

add('core1-5.5','client-connectivity-sequence','Limited access, portals, interference and network configuration faults',
 'A connected status icon is not an end-to-end test. Confirm link or wireless association, then inspect address, subnet, gateway and resolver configuration. A link-local IPv4 address often indicates a missing DHCP lease, but document the actual intended network rather than treating any unfamiliar address as invalid. Local communication with remote-IP failure suggests a different boundary from successful remote-IP access with failed names. Captive portals may require an approved sign-in step; proxy, VPN, firewall or management policy can also affect application behavior. Intermittent wireless failures need signal, roaming, interference, load and driver evidence. Slow performance can involve latency, loss, congestion or the server rather than a need to replace the access point. Check whether one client, one subnet or everyone is affected to narrow scope. Record a reproducible test and avoid deleting profiles or resetting stacks before preserving useful evidence.',
 [('Link/IP/DNS/application','Each successful stage proves less than complete service readiness.'),('Captive portal','Network access can require an authorized browser-based admission step.'),('Latency/loss/congestion','Distinct performance evidence needs correlation.'),('Scope','One host, segment or service failure suggests different hypotheses.')],['Link/association','Address and gateway','Remote IP and name','Application/session'],
 'A laptop has a valid-looking lease and can reach remote IPs but not hostnames. Which boundary should be examined?', 'DNS resolver configuration and actual query results', 'Replace the RAM immediately', 'Assume every wireless association failure is identical', 'Working remote-IP access narrows the issue toward name handling or application configuration.',
 'One client repeatedly drops Wi-Fi while nearby clients remain stable. What is a useful comparison?', 'Client adapter/driver, band support, signal and roaming history versus unaffected clients', 'Replace every site router without evidence', 'Disable all identity controls permanently', 'Comparing affected and unaffected paths helps isolate a client-specific fault.',
 ['Write a staged connectivity test with expected observations.','Create one DHCP, one DNS and one captive-portal case.','Preserve timestamps and before/after state.'])

add('core1-5.6','printer-fault-boundaries','Print defects, feeding faults and client-versus-engine diagnosis',
 'Use a printer’s own test output and the scope of affected clients to distinguish image-engine and job-path faults. A clear internal page with one failing workstation points toward that client’s application, driver, queue, format or connection; identical defects on internal pages implicate device-side processes or media. Jams, double feeding and skew can involve paper condition, loading, guides, rollers or separation components rather than the image drum. Faint, streaked, repeated or unfused output has different plausible causes; identify the technology before applying a fix. A device that repeatedly cycles or reports a specific error should be investigated under its model documentation. Firmware, job languages, page settings and authorized secure-release state can change behavior without a physical failure. Preserve the initial symptom, use supported consumables and safe procedures, and verify both a local test and a representative user job afterward.',
 [('All clients versus one','Scope helps locate the common failing boundary.'),('Internal test page','Bypasses much of the client-generated job path.'),('Feed versus image defect','Media handling and marking processes are distinct.'),('Error/state evidence','Use model-specific meanings rather than a universal guess.')],['User/application job','Driver/queue/connection','Printer interpreter','Feed and marking engine'],
 'Every client and the printer’s internal page show the same vertical streak. What is the useful next boundary?', 'The device’s imaging/consumable path under the model procedure', 'Only one user’s browser profile', 'Only a mapped drive letter', 'A self-generated page removes many client dependencies from the symptom.',
 'Several sheets feed at once but image quality is otherwise good. What should be examined?', 'Supported media, loading and separation/feed components', 'Only the DNS resolver', 'Only the document password', 'Multiple-sheet feeding is primarily a media-handling symptom.',
 ['Classify six sample symptoms by job, image or feed boundary.','Plan internal and client test pages.','Write stopping criteria for hot/high-voltage service areas.'])

add('core2-1.6','windows-settings-map','Windows settings, accessibility and power behavior',
 'Choose a settings area based on the affected function. Devices and Printers, sound, accounts, networking, applications and accessibility expose different configuration boundaries. File Explorer options can change hidden-item and filename-extension visibility; a hidden extension can make an executable look like a document. Default-app associations affect how a file opens without changing its contents. Indexing affects search results and workload behavior rather than guaranteeing file existence. Sleep, hibernation, standby and shutdown differ in retained state, power use and resumption dependencies; exact behavior depends on hardware, firmware and OS configuration. Lid-close and power-button actions can explain a reported shutdown or missing session. Use power and accessibility settings to meet the user’s actual needs instead of disabling useful features indiscriminately. Settings interfaces vary by version, and organizational policy can override local selections. Record the before state and verify the observed user workflow after a change.',
 [('Sleep/hibernate/shutdown','Different state and power transitions with platform-specific behavior.'),('Filename extensions','Display settings can conceal the true file type.'),('Default apps/indexing','Opening behavior and search behavior are separate.'),('Policy/local setting','A local control does not always determine the effective configuration.')],['User symptom','Relevant settings area','Local and organizational policy','Verified workflow'],
 'A file appears to be a PDF because extensions are hidden, but it is actually executable. What setting helps reveal the distinction?', 'Display known filename extensions and verify the file type', 'Increase speaker volume', 'Change only the desktop background', 'Visible extensions reduce one form of ambiguity but do not by themselves prove a file is safe.',
 'A laptop appears to turn off whenever its lid closes. What should be checked before replacing hardware?', 'Configured lid-close action and supported sleep/hibernate behavior', 'Only the printer driver', 'Assume every lid event is a battery failure', 'The observed transition may be the configured power action rather than a hardware defect.',
 ['Map five user symptoms to settings areas.','Compare three power transitions using a fictional state table.','Include an accessibility requirement and a policy-controlled exception.'])

add('core2-1.10','application-requirements','Application architecture, dependencies, deployment and business impact',
 'Installation success depends on architecture, OS version, supported dependencies, licensing, privileges and resources. A 32-bit versus 64-bit requirement is not interchangeable with the storage size of an installer. Graphics-intensive work can require supported GPU capabilities and video memory as well as system RAM and CPU capacity. Hardware tokens, driver support and external devices can be application dependencies. A downloadable package, mounted ISO, physical medium and managed image are distribution methods rather than automatic trust guarantees. Obtain software through approved sources and verify applicable signatures or hashes against trusted references. Installation can modify services, drivers, file associations, network traffic and shared runtimes, affecting other users or applications. Plan testing, communication, authorization and recovery appropriate to the business impact. Do not turn off security controls merely because an installer asks; establish the actual compatibility or policy issue first.',
 [('Architecture/OS/dependency','Separate compatibility constraints.'),('GPU/VRAM/RAM/CPU','Distinct resource requirements that must meet the workload.'),('Distribution/trust','Delivery method does not itself prove authenticity.'),('Device/network/business impact','Deployment can affect more than the initiating user.')],['Trusted package','Compatible platform/dependencies','Authorized deployment','Business workflow verification'],
 'An application requires a specific runtime and GPU feature level. What must deployment verify?', 'Both dependencies and the supported platform, not merely enough free storage', 'Only the installer filename', 'Assume any 64-bit OS supplies every runtime and GPU feature', 'Compatibility requirements are independent dimensions that need explicit checks.',
 'An installer requests that all endpoint protection be disabled. What should support do?', 'Investigate documented requirements and use the approved exception process if justified', 'Disable every control indefinitely', 'Treat the request as proof the software is trustworthy', 'A request for broad privilege or reduced protection is not evidence of necessity or safety.',
 ['Build an application prerequisite checklist.','Compare three approved distribution methods.','Identify service, driver, network and rollback implications for a fictional deployment.'])

add('core2-1.11','cloud-productivity','Productivity identity, licensing, sync and collaboration boundaries',
 'Cloud productivity combines application, account, licensing, storage, sharing and network dependencies. A valid sign-in does not prove that the correct license, service entitlement or document permission has been assigned. Identity synchronization coordinates supported account information between systems; it is not the same operation as synchronizing files. Folder sync can be selective, delayed, conflicted or restricted by capacity and policy. A local cached file may remain available offline while a newer cloud version has not arrived. Calendar, mail, instant messaging, meetings and shared documents each have their own settings and user expectations. Version history can help recover changes but must be distinguished from an independent backup and applicable retention guarantees. Before broadening sharing to solve access denied, identify the intended recipient and minimum permission. Verify both directions of a sync workflow with harmless test content rather than assuming an icon means everything is complete.',
 [('Identity sync/file sync','Different objects and control planes.'),('License/permission','Service entitlement and resource authorization are separate.'),('Offline cache/cloud state','A visible local file is not proof of current remote state.'),('Version history/backup','Recovery behavior depends on retention and independence.')],['Identity and entitlement','Service connection','Resource sharing','Verified content state'],
 'A user signs in successfully but cannot use the required application. What should be checked?', 'The assigned license, service entitlement and relevant authorization', 'Only the monitor cable', 'Assume authentication grants every product feature', 'Successful identity proof and product/resource access are different checks.',
 'A deleted file disappears from synchronized devices. What does that show?', 'Synchronization may propagate deletion; it is not automatically an independent backup', 'Every sync client is a permanent historical archive', 'Cloud storage cannot reflect user mistakes', 'Protection against propagated changes requires appropriate versioning, retention or independent recovery.',
 ['Draw identity sync separately from file sync.','Design a least-privilege document-sharing example.','Specify an offline/edit/conflict verification test.'])

add('core2-2.1','access-control-layers','Physical barriers, identity factors and access mechanisms',
 'Physical security addresses entry, movement, equipment access and evidence. Bollards restrict vehicle paths, fences and locks define barriers, vestibules can control sequential entry, and guards provide human observation and response. Cameras, alarms and motion sensors detect or deter under a configured process but do not all physically block an intrusion. Badge readers, keys, smart cards, mobile credentials and biometrics use different identity and possession characteristics. Biometric use also raises enrollment, matching-error, privacy and fallback questions. Logical access uses subjects, resources and rules: least privilege limits permissions, ACLs specify applicable access, and zero trust rejects unconditional trust based only on location. MFA combines different factor categories; two passwords or password plus PIN normally remain knowledge factors. SSO reduces repeated sign-ins through an identity arrangement but does not eliminate authorization. SAML is one federation-related assertion mechanism; just-in-time privileged access limits standing authority under a controlled workflow.',
 [('Prevent/detect/respond','Barrier, observation and intervention are different functions.'),('Knowledge/possession/inherence','Factor categories are distinct from the number of secrets entered.'),('SSO/federation/authorization','Sign-in convenience does not grant every resource permission.'),('IAM/PAM/JIT/MDM/DLP','Identity, privileged access, time-bounded authority, device management and data-loss controls have distinct scopes.')],['Physical entry','Identity proof','Resource authorization','Evidence and review'],
 'A system requests a password and a PIN as its only two checks. What should a technician explain?', 'These are normally two knowledge secrets, not two different factor categories', 'Any two prompts guarantee MFA', 'A PIN is always a physical possession factor', 'Factor diversity concerns categories, not prompt count.',
 'A camera records someone tailgating through an unlocked door. Which conclusion is supported?', 'The camera supplies evidence, but the entry-prevention design still needs review', 'Recording guarantees physical prevention', 'A longer recording filename restricts entry', 'Detective evidence should not be mistaken for an access barrier.',
 ['Classify a door lock, badge policy, camera alert and guard response.','Design a two-factor sign-in and a fallback process.','Draw SSO authentication separately from application authorization.'])

add('core2-2.3','wireless-authentication','Wireless protection, RADIUS, TACACS+ and Kerberos distinctions',
 'Wireless security mode, encryption and identity backend are related but separate choices. WPA2 and WPA3 describe security generations with personal and enterprise arrangements; support depends on clients, infrastructure and configuration. AES-based modern protection should not be confused with older TKIP, and a hidden SSID is not a cryptographic control. In enterprise access, 802.1X coordinates port-based authentication using an authenticator and an authentication service with a suitable EAP method. RADIUS is commonly used as an AAA protocol in network access. TACACS+ is often associated with device-administration AAA and separates functions differently from RADIUS; use the platform’s documented support. Kerberos is a ticket-based authentication system with dependencies such as trusted identities, service naming and time. It is not simply a wireless cipher. Verify certificates and the expected authentication server where the design requires them; otherwise an apparently familiar network name can mislead users into trusting an unintended endpoint.',
 [('WPA2/WPA3','Security-mode families, not proof of correct deployment.'),('TKIP/AES','Different cryptographic mechanisms; legacy compatibility choices can weaken a design.'),('RADIUS/TACACS+','AAA protocols commonly used for network access and administration contexts.'),('Kerberos','Ticket-based authentication with identity, naming and time dependencies.')],['Client supplicant','Authenticator/AP or switch','AAA/EAP service','Authorized network access'],
 'An enterprise Wi-Fi client accepts any server certificate without validation. What is the concern?', 'It may fail to authenticate the expected identity service and expose credentials to an unintended endpoint', 'A familiar SSID makes certificate checks irrelevant', 'Changing channel width verifies the server identity', 'Network names and radio settings do not establish trusted authentication-server identity.',
 'A technician calls Kerberos an encryption mode equivalent to WPA3. What is the correction?', 'Kerberos is a ticket-based authentication system; wireless protection modes solve different requirements', 'They are two names for the same cipher', 'Kerberos is only a cable pinout', 'Distinguish identity protocols from link-security modes.',
 ['Draw an enterprise wireless authentication path.','Mark where a client must validate the expected server.','Compare RADIUS, TACACS+ and Kerberos by purpose rather than brand.'])

add('core2-2.5','attack-mechanisms','Social engineering and application/network threat boundaries',
 'Identify the mechanism and evidence before assigning a confident attack label. Phishing can arrive through email, text, voice or QR codes; spear phishing narrows targeting and whaling focuses on high-value roles. Impersonation, pretexting, shoulder surfing, tailgating and discarded-material collection exploit different human or physical boundaries. BEC can use a compromised account or convincing impersonation without an obvious malicious attachment. A rogue wireless lookalike is a different path from an application injection flaw. SQL injection changes a database-command context, while XSS introduces script into a browser execution context; both require context-appropriate preventive controls. Denial of service targets availability, and distributed sources do not make every outage a DDoS event. Credential guessing, replay, spoofing and on-path observation/alteration have different preconditions. An unpatched or end-of-life system is a weakness or risk condition, not proof that a specific exploit succeeded. Preserve evidence and follow authorized reporting rather than testing against unrelated systems.',
 [('Phishing/vishing/smishing/QR','Delivery channels can differ while the social objective is similar.'),('Spear/whaling/BEC','Targeting and business impersonation concepts overlap but are not identical.'),('SQL injection/XSS','Database-command context versus browser script context.'),('DoS/DDoS/on-path/spoofing','Availability pressure, distributed sources, path control and identity/address misrepresentation differ.')],['Entry or delivery path','Trust boundary crossed','Observed behavior','Containment and verification'],
 'A payroll email requests new bank details with no attachment. Can it still be malicious?', 'Yes; business-email compromise or impersonation can seek a fraudulent action without an attachment', 'No; only executable attachments can carry a social attack', 'No; a display name proves authority', 'The requested action and independent verification matter more than the presence of a file.',
 'Untrusted text is inserted into a database query as executable syntax. Which boundary is implicated?', 'Database command construction and parameter handling', 'Only a monitor refresh-rate setting', 'Only wireless channel selection', 'The mechanism concerns separation of query data from command structure.',
 ['Classify five fictional attack reports by mechanism and uncertainty.','Write an independent verification path for a payment change.','Compare parameterized database use with browser output encoding.'])

add('core2-2.6','a-plus-malware-sequence','Exam cleanup sequence versus real incident authority',
 'Know the sequence and the reason behind a controlled malware response without applying it blindly. The A+ objective presents a simplified small-office cleanup flow: investigate symptoms, quarantine, manage the relevant Windows Home restore state, remediate, update anti-malware, use appropriate scan environments, reimage/reinstall where required, schedule ongoing protection, restore the relevant recovery configuration and educate the user. In an actual organization, the authorized incident plan, evidence preservation, legal requirements and recovery policy determine what a technician may change. Disabling recovery or deleting infected files can destroy evidence or remove a needed restore option, so it is not an automatic first step in every incident. Isolation must be scoped and coordinated to limit spread while preserving required access for responders. A trusted rebuild can be preferable when confidence in cleanup is inadequate. Recovery is not complete until the original entry point, persistence, affected identities and post-restoration operation have been addressed.',
 [('Investigate/contain','Establish evidence and limit authorized impact.'),('Cleanup/rebuild','Choose a trustworthy recovery route appropriate to the compromise.'),('Restore-state change','A context-specific step, not universal authority to disable recovery.'),('Verification/education','Confirm safe operation and improve future behavior.')],['Verify symptoms','Contain under plan','Eradicate or rebuild','Recover and verify','Educate and improve'],
 'A technician has a basic malware checklist but the organization requires forensic preservation. Which instruction controls real actions?', 'The authorized organizational incident and evidence-handling process', 'A memorized checklist automatically authorizes deletion of all logs', 'The fastest action is always correct', 'Study sequences explain concepts; actual authority and preservation requirements remain applicable.',
 'A system is restored but the stolen service credential is still active. What remains incomplete?', 'Identity containment and the response plan’s recovery verification', 'Nothing; copying files back guarantees resolution', 'Only changing the desktop theme', 'Recovery must address the compromise and its dependencies, not only file availability.',
 ['Build a response sequence with purpose and authority for each stage.','Mark evidence-changing actions that need explicit coordination.','Define what proves a restored system is ready to return.'])

add('core2-2.7','workstation-hardening','Workstation baseline, accounts and data-at-rest protection',
 'Harden a workstation for its role instead of applying every setting without considering usability and recovery. Use supported updates, appropriate endpoint protection, an intentional service set and restricted administrative authority. Screen-lock timeouts, account expiration, failed-attempt handling and permitted sign-in times address different risks and must follow policy. Long, unique credentials and protected password-manager use are more important than reusing a predictable pattern across accounts; do not treat routine forced password changes as a universal substitute for compromise detection. Disable unnecessary default or guest access and replace default management credentials where applicable. Firmware passwords protect a different boundary from OS identities. Data-at-rest encryption needs an approved recovery-key process; otherwise a hardware or firmware change can become a data-loss event. AutoRun and removable-media behavior should match policy. Preserve user data and required business services while testing the baseline, and verify effective settings rather than only the intended template.',
 [('Baseline/updates/services','Configuration and maintenance must fit the actual role.'),('Lockout/timeout/expiration','Different identity/session controls with different availability effects.'),('Firmware/OS authentication','Separate authority boundaries.'),('Encryption/recovery','Confidentiality must be paired with usable authorized recovery material.')],['Role requirements','Secure configuration','Identity/session limits','Verified recovery and workflow'],
 'A team enables disk encryption but loses the only recovery-key record. What new operational risk exists?', 'Authorized recovery may fail after a triggering hardware or trust-state change', 'Encryption automatically creates unlimited recovery keys', 'An administrator password always substitutes for every recovery key', 'Key protection and key recoverability both need design and evidence.',
 'A technician disables an unfamiliar service that supports the business application. What was missing?', 'Role/dependency analysis and a tested change plan', 'Only a longer username', 'A different wallpaper', 'Hardening should reduce unnecessary exposure without blindly breaking required functions.',
 ['Create a role-based baseline and its rationale.','Separate account, session and firmware controls.','Plan a recovery-key verification without revealing any real key.'])

add('core2-2.8','mobile-security-lifecycle','Managed mobile security and lost-device decisions',
 'Mobile protection spans enrollment, encryption, lock methods, updates, application sources, network behavior and the device’s lifecycle. A screen lock protects an interactive access path but does not prove all stored data is encrypted. Biometrics, PINs and patterns have different implementation and recovery considerations. Configuration profiles and MDM policies can enforce business requirements, but BYOD designs must distinguish corporate data/actions from personal ownership and privacy. Rooting or jailbreaking can change the platform’s trust and support assumptions; developer mode is not identical to a confirmed compromise. Application and OS updates have separate channels and eligibility. Lost-device actions such as location, remote lock or wipe require authorized scope and an understanding of connectivity, data consequences and platform behavior. A wipe command being issued is not proof it executed. Backups, account-session control, token revocation and documented follow-up can remain necessary even when device recovery is unlikely.',
 [('Lock/encryption','Interactive access and stored-data confidentiality are distinct.'),('BYOD/corporate','Ownership affects permissible management scope.'),('Command issued/executed','Remote action needs status verification.'),('Rooting/developer mode/compromise','Related but different evidence and support conditions.')],['Enrollment and ownership','Baseline and patching','Loss/incident response','Verified action and access cleanup'],
 'An administrator issues a remote wipe to an offline device. What can they conclude immediately?', 'The command was requested; execution still needs supported status verification', 'The device’s data is definitely gone', 'Every cloud session was automatically revoked', 'Requesting an action and verifying its outcome are separate facts.',
 'A BYOD phone contains both personal and corporate data. What should determine a response?', 'The authorized ownership, management and data-protection policy for that device', 'Assume corporate enrollment permits every action on all personal data', 'Let an unrelated employee decide without evidence', 'Management scope and authority must be established before impactful remote actions.',
 ['Design a fictional BYOD and corporate-owned baseline.','Compare lock, selective corporate-data action and full-device wipe concepts.','Write verification and follow-up steps for an offline lost device.'])

add('core2-2.10','router-hardening','SOHO router exposure, automatic mapping and management',
 'A small-office boundary should expose only services that have a justified purpose and a maintained owner. Change default administration credentials, keep supported firmware and protect configuration backups. Restrict management to an approved path; a publicly reachable interface with default credentials is not made safe by an obscure URL. IP filtering, firewall rules, content filtering and a screened subnet address different traffic and placement requirements. Port forwarding maps selected inbound traffic to an internal target and can expose a service that was previously private. UPnP or other automatic mapping features can change exposure depending on implementation and policy; review the actual behavior rather than assuming convenience equals authorization. Wireless settings include supported encryption, guest policy and placement. Hiding an SSID does not establish secrecy or access control. Test the resulting external exposure and internal segmentation from the relevant observation points after a change.',
 [('Management/data plane','Administrator access and ordinary forwarded traffic differ.'),('Port forwarding/UPnP','Explicit and automatic mapping both affect exposure.'),('Screened subnet/guest segment','Placement must be paired with enforced policy.'),('SSID visibility/encryption','Network-name advertisement is not cryptographic protection.')],['External service need','Boundary rule/mapping','Internal target and owner','Exposure and segmentation test'],
 'A router’s admin page is reachable from the internet with a default password. What should be prioritized?', 'Remove unnecessary management exposure and configure approved authentication/access', 'Only rename the SSID', 'Only change a client wallpaper', 'Reachability and weak authentication are separate risk factors that need direct controls.',
 'A user changes the SSID and assumes neighbors cannot access an open WLAN. What is the correction?', 'A new or hidden name does not replace supported authentication and encryption', 'The SSID itself is an encryption key', 'Guest isolation is guaranteed by the name length', 'Names are identifiers, not security boundaries.',
 ['Create an inbound-service inventory with owners and reasons.','Draw management and guest paths separately.','Plan an authorized before/after exposure verification.'])

add('core2-2.11','browser-boundaries','Browser privacy, trust, extensions and secure connections',
 'A browser is an application platform with its own update, extension, identity, storage and network settings. Obtain installers and extensions from approved sources, then verify relevant publisher/signature or trusted hash information where available. A matching hash from an untrusted source does not by itself establish authenticity. Extensions can request powerful access and may change behavior after updates or account compromise. A valid HTTPS connection protects a transport relationship with the named site under its trust model; it does not prove the site is honest or the content is harmless. Certificate warnings need investigation of name, trust, date and possible interception rather than routine bypass. Private browsing limits selected local persistence but does not make activity invisible to sites, employers or network operators. Clearing cache, cookies, history and synchronized account data affects different things. Secure DNS, proxy settings, pop-up controls and content blocking also have distinct scopes and policy implications.',
 [('HTTPS/content trust','Transport identity/protection is not a complete reputation or safety judgment.'),('Private mode/anonymity','Reduced local persistence is not universal invisibility.'),('Cache/cookies/history/sync','Different stored data and account-linked behavior.'),('Extension permission/publisher','Review authority and update provenance, not only a store listing.')],['Trusted browser build','Extension and account authority','Connection validation','Local/cloud data behavior'],
 'A private-browsing window is used on a managed corporate device. Is activity automatically hidden from the organization’s network controls?', 'No; private mode does not remove network, device-management or site visibility', 'Yes, it encrypts all metadata from every observer', 'Yes, it bypasses all organizational policy', 'Browser persistence controls are not a universal anonymity system.',
 'A site presents a certificate-name mismatch before a sensitive login. What should happen?', 'Investigate the expected name, trust and network context before entering credentials', 'Always bypass the warning because the page looks familiar', 'Disable all certificate checks permanently', 'Visual familiarity does not resolve a failed connection identity check.',
 ['Compare effects of clearing cache, cookies and synchronized data.','Review fictional extension permissions.','Build a certificate-warning investigation checklist with safe stopping criteria.'])

add('core2-3.1','windows-fault-boundaries','Windows startup, services, profiles and resource faults',
 'Distinguish a failure before firmware, before the OS loader, during OS startup, at sign-in or inside one application. A no-OS message can reflect boot selection or storage visibility, not necessarily erased files. Stop errors can involve drivers, hardware or kernel-level components; collect the code, timing, recent changes and available diagnostic evidence before choosing a fix. A service that fails to start may have dependency, identity, configuration or resource problems. Slow profile load can involve local profile state, network resources and policy processing. Time drift can affect logs and authentication, so do not treat a corrected clock display as the entire root-cause analysis. Memory pressure and USB-controller resource warnings are different from disk capacity exhaustion. Startup repair, restore points, driver rollback and a clean rebuild have different purposes and data/availability impacts. Choose the least speculative supported recovery that fits the observed boundary, with backups and recovery material ready.',
 [('No OS/stop error/app crash','Different layers of failure.'),('Service/profile/time','Identity and dependency evidence can matter as much as hardware.'),('Resource pressure','Identify the actual constrained resource.'),('Rollback/repair/rebuild','Different recovery scopes and side effects.')],['Firmware/boot','OS services','Identity/profile','Application workload'],
 'An application crashes but the rest of the OS remains stable. What is a reasonable starting scope?', 'The application’s logs, dependencies, data and recent changes', 'Assume every app crash proves motherboard failure', 'Erase all profiles before collecting evidence', 'The observed boundary supports a narrower initial investigation.',
 'Authentication and event correlation fail while a workstation clock drifts. What should be checked?', 'Time source/configuration and the broader cause of drift, with correlated evidence', 'Only the font size of the clock display', 'Delete all logs to remove inconsistent times', 'Time is an operational dependency for both identity and reliable timelines.',
 ['Map five symptoms to startup/service/profile/application boundaries.','Build a timestamped recent-change record.','Compare the scope and data implications of three recovery options.'])

add('core2-3.2','mobile-app-diagnosis','Mobile application, update, resource and sensor symptoms',
 'A mobile application may fail to launch, update, install, respond or close for different reasons. Confirm supported OS/application versions, available capacity, network access, account entitlement and required permissions. An update may require power, storage and a supported service path rather than a factory reset. Cache corruption and user data are different things; deleting app storage can remove valuable local information, so follow the documented preservation and recovery approach. Battery drain and random reboot symptoms can involve application workload, radio conditions, hardware or thermal behavior. Rotation problems can result from orientation lock, application design, sensor state or hardware. Bluetooth, Wi-Fi and NFC connectivity failures need the relevant radio/service boundary rather than one generic reset. Compare one affected app with other apps and one affected device with unaffected devices to isolate scope. Preserve useful logs, account state and recent-change information before clearing it.',
 [('App cache/data','Different contents and recovery consequences.'),('Install/update/launch','Different lifecycle stages with distinct requirements.'),('Autorotation','Settings, app behavior and sensor path may each matter.'),('Power/resource/radio','Battery symptoms can have several measurable causes.')],['Supported app/platform','Resources and entitlement','Permissions/sensors/radios','Reproduced app workflow'],
 'An app cannot save and the device is nearly out of storage. What should be checked first?', 'Storage requirements and an approved data-protecting cleanup plan', 'Replace the touchscreen immediately', 'Clear every app’s data without asking about local files', 'The symptom and capacity evidence support a targeted resource investigation.',
 'Only one application refuses to rotate while others rotate normally. What is a useful next check?', 'That app’s orientation support and settings before assuming sensor failure', 'Replace every sensor immediately', 'Change only the cellular plan', 'Working rotation elsewhere narrows the likely fault boundary.',
 ['Build an app lifecycle fault table.','Separate cache cleanup from data deletion.','Plan comparative tests for one-app and whole-device symptoms.'])

add('core2-3.3','mobile-compromise-evidence','Mobile security indicators and what they do not prove',
 'Treat unusual mobile behavior as evidence to investigate, not a certain attribution. Unexpected profiles, sideloaded applications, excessive advertising, unusual account sessions or unexplained data transfer can suggest a security or policy issue, but battery drain or high traffic can also have legitimate causes. Identify the application source, permissions, management enrollment, recent changes and account context. Developer mode, root access and jailbreaking affect platform controls and support assumptions differently; their presence alone does not describe every consequence. Fake security warnings may try to induce a call, installation or payment, so do not follow the warning’s embedded instructions as the trusted recovery process. Protect the user and organizational data, preserve relevant evidence and escalate under the approved mobile response plan. Removing an app or wiping a phone can destroy information and affect personal data, especially in BYOD settings. Verify account/session and token actions separately from device cleanup.',
 [('Indicator/proof','One symptom rarely establishes the entire incident.'),('Sideload/profile/root','Different changes to application and device trust.'),('Fake warning/trusted support','Use a known independent support path.'),('Device/account scope','Cleaning a device does not automatically revoke every session.')],['Observed symptom','Application/profile/account context','Authorized containment','Verified device and identity recovery'],
 'A pop-up claims the phone is infected and demands payment through its own link. What is the safe next path?', 'Use the known support/reporting process rather than trust the pop-up’s instructions', 'Pay immediately because the warning says urgent', 'Install every suggested tool', 'A warning can itself be the social-engineering delivery mechanism.',
 'A device is wiped after an account compromise. Are all cloud sessions necessarily invalidated?', 'No; verify the identity/session recovery actions separately', 'Yes, every provider always revokes every token automatically', 'Only the wallpaper needs checking', 'Device storage state and service-side sessions are separate boundaries.',
 ['Create a mobile indicator triage record distinguishing facts and hypotheses.','Map app, profile, device and account evidence.','Plan authorized escalation and post-recovery verification.'])

add('core2-3.4','pc-security-diagnosis','PC alerts, persistence and browser-related security faults',
 'A PC security complaint may involve genuine endpoint detection, fake warnings, changed files, denied network access, failed updates or browser redirection. Verify which component generated an alert, its time, affected identity and related events before trusting the text. A browser pop-up that resembles an OS warning does not inherit system authority. Missing or renamed files can result from user actions, synchronization, software faults or malicious activity; preserve evidence and backups while narrowing the cause. Recurrent redirects can arise from extensions, proxy or DNS configuration, policy or deeper persistence, so resetting one homepage may not address the source. A failed OS update can have capacity, service, compatibility, network or security causes. Identify whether one browser, profile, application, user or the entire host is affected. Follow incident procedures when evidence supports compromise and use a trusted recovery path with verification of persistence and affected credentials.',
 [('Real alert/fake alert','Identify provenance rather than trust appearance.'),('File symptom/cause','A changed file needs evidence before attribution.'),('Browser/profile/host','Different scope guides targeted tests.'),('Cleanup/persistence','Removing a visible symptom is not proof of eradication.')],['Alert provenance','Scope and correlated evidence','Persistence/entry investigation','Trusted recovery verification'],
 'A browser security alert asks the user to call an unknown number. What should support establish?', 'Whether it is a webpage or a trusted security component, using an independent support path', 'The phone number is trusted because it appears in red', 'The page can authorize installation of any remote-control software', 'Appearance and urgency are not authority.',
 'A redirect returns after clearing the homepage setting. What should be investigated?', 'Extensions, policies, proxy/DNS and other persistence mechanisms with evidence', 'Only keep changing the homepage forever', 'Only replace the monitor', 'Recurrence suggests the underlying source remains active.',
 ['Write an alert-provenance checklist.','Compare browser-only and host-wide hypotheses.','Define evidence and recovery checks for a recurring symptom.'])

add('core2-4.1','support-records','Ticket quality, assets, SLAs and useful knowledge articles',
 'A support record should allow another person to understand the user, device, business impact, exact symptom, time, scope, actions and current state without exposing credentials or unnecessary personal information. Severity and priority are related but not identical; organizational criteria determine urgency and escalation. Progress notes should distinguish observations, hypotheses and results so the next technician does not repeat failed work. Asset records and a CMDB provide inventory and configuration/dependency information; asset tags, ownership, warranty, licensing and lifecycle status support procurement, service and retirement. A knowledge article turns a verified recurring solution into reusable guidance with prerequisites, scope, symptoms, safe steps and validation. An incident report, SOP, onboarding/offboarding checklist and internal or external SLA have different purposes. An SLA expresses agreed service expectations; it is not proof that a particular system is healthy or that a fix has been validated.',
 [('Observation/hypothesis/result','Different statements must remain distinguishable.'),('Asset inventory/CMDB','Identity and configuration/dependency records support lifecycle work.'),('Incident/SOP/knowledge article','Event record, repeatable procedure and reusable troubleshooting guidance differ.'),('SLA/escalation','Agreed expectations and response routes need context.')],['User/device/impact','Evidence and actions','Escalation/current state','Verified resolution and knowledge'],
 'An escalated ticket says only still broken. What information is most useful to add?', 'Reproduction steps, scope, evidence, actions tried and the current state', 'A shared administrator password', 'Only the technician’s frustration', 'A factual handoff supports the next test and avoids duplicating work.',
 'A knowledge article was written after an unverified workaround. What should occur before treating it as a standard fix?', 'Validate scope, prerequisites, side effects and the actual resolution evidence', 'Assume publication proves correctness', 'Remove all verification steps to shorten it', 'Documentation should preserve tested knowledge rather than turn a guess into authority.',
 ['Write a fictional ticket with no real personal data.','Create a resolution note separating evidence from inference.','Convert one verified case into a scoped knowledge article.'])

add('core2-4.2','change-governance','Standard, normal and emergency changes with recovery criteria',
 'Change control connects a business need to authorized, reviewable implementation and recovery. Record the purpose, scope, affected systems, dependencies, risk, responsible staff and intended timing. A standard change may be pre-authorized under a defined procedure, while a normal change follows its applicable assessment/approval process. An emergency process can accelerate necessary work but does not erase accountability, evidence or follow-up. A maintenance window coordinates impact; a change freeze constrains timing under organizational rules. A backup plan protects selected data, while a rollback plan describes returning the service or configuration to an acceptable state; they are not identical documents. Sandbox tests, peer review and implementation checks reduce uncertainty but do not guarantee production success. Define measurable acceptance and rollback triggers before deployment. Afterward, verify functionality and security, obtain appropriate user/business acceptance and update configuration and support records.',
 [('Backup/rollback','Data protection versus a service/configuration reversal plan.'),('Standard/normal/emergency','Different authorization processes, not different obligations to be accountable.'),('Window/freeze','Approved timing and restricted timing concepts.'),('Acceptance/verification','Business outcome and technical evidence both matter.')],['Request and impact','Approval and readiness','Controlled implementation','Verify, accept or roll back'],
 'A team has a data backup but no plan to undo a failed network-policy change. What is missing?', 'A service/configuration rollback plan with clear triggers and responsibility', 'Only a different ticket color', 'Nothing; all backups automatically reverse every policy effect', 'Restoring files and reversing a service-impacting configuration are different recovery tasks.',
 'An emergency fix bypasses ordinary scheduling. What still needs to be retained?', 'Authorization under the emergency process, evidence, verification and required post-change review', 'No records because speed removes accountability', 'Only the final filename', 'Emergency procedures change timing and routing, not the need to control consequences.',
 ['Create a change request with dependencies and risk.','Write distinct backup and rollback plans.','Define acceptance and rollback thresholds plus a post-change review.'])

add('core2-4.4','safety-and-handling','ESD, grounding, lifting and hazardous service limits',
 'Protect people first, then equipment and data. Shut down and disconnect power before ordinary internal PC service, following the model’s documented battery-isolation procedure where relevant. Appropriate ESD straps, mats and antistatic packaging reduce electrostatic damage, but they are not permission to work on energized high-voltage equipment. Equipment grounding and safe power wiring serve electrical safety functions distinct from simply preventing static damage. Handle components by appropriate edges, protect connectors and avoid stacking parts on conductive or unsuitable surfaces. Cable management reduces trip, strain and airflow hazards. Use suitable lifting methods and assistance for heavy equipment; a rack installation adds stability and load considerations. Eye protection or respiratory protection may be needed for the particular approved task, not chosen at random. Fire, liquid, swollen-battery, burning-smell and hazardous-component conditions require appropriate stopping and escalation rather than improvised repair. Follow the applicable safety documentation and organizational procedure.',
 [('ESD/electrical safety','Protecting electronics from static is not the same as protecting a person from hazardous voltage.'),('Grounding/packaging','Electrical installation and component storage solve different problems.'),('Lifting/rack stability','Weight, balance and handling plans matter.'),('Stop/escalate','A hazard changes the task boundary.')],['Identify task/hazards','Isolate power and protect data','Use appropriate handling controls','Verify safe completion'],
 'A technician wears an ESD strap and proposes servicing an energized power supply. What is the correction?', 'An ESD strap does not make hazardous energized service safe or authorized', 'Static protection removes every electrical hazard', 'Any metal tool is an approved discharge method', 'ESD and high-voltage safety are different control problems.',
 'A heavy UPS must be installed high in an unstable rack. What should happen?', 'Review the rack/load and safe handling plan before installation', 'Lift it alone as quickly as possible', 'Assume a rack label guarantees stability', 'Mechanical safety and equipment placement need a deliberate plan.',
 ['Identify hazards for three service tasks.','Separate ESD controls from electrical isolation.','Write a stopping/escalation condition and a safe handling plan.'])

add('core2-4.5','environment-and-power','Cooling, humidity, dust, brownouts and environmental disposal',
 'Environmental control is part of reliable support. Maintain airflow paths, suitable equipment placement and the temperature/humidity ranges specified by the relevant hardware and facility procedures. Excess heat can cause throttling or shutdown; dust and blocked ventilation can worsen heat removal. Very dry conditions can increase static concerns, while inappropriate moisture creates different hazards. Use approved cleaning tools and techniques; a household vacuum or unrestricted compressed-air practice can damage electronics or create static, debris or mechanical problems. A surge suppressor addresses certain transient conditions but does not provide the same stored-energy support as a UPS. Brownout, blackout and surge describe different power events, and a UPS’s runtime/load and battery health must be verified. Disposal of batteries, toner and other equipment requires the appropriate safety information and approved environmental route. A material safety data sheet or safety data sheet supports handling information but does not replace the organization’s operational instructions.',
 [('Temperature/humidity/airflow','Related environmental factors with model-specific limits.'),('Surge/brownout/blackout','Different electrical supply events.'),('UPS/surge suppressor','Energy support and transient protection are not identical capabilities.'),('Handling/disposal documentation','Use the relevant product and organizational procedures.')],['Environmental readings','Equipment load/placement','Power protection design','Maintenance and disposition evidence'],
 'A surge strip is installed and users expect ten minutes of runtime during a blackout. What should be explained?', 'A surge suppressor alone does not supply the stored-energy function of a suitable UPS', 'Every surge strip includes unlimited battery runtime', 'Changing the outlet label adds backup energy', 'Protection against a transient and continued power during an outage are different requirements.',
 'A rack overheats after boxes are placed against its intake. What should be investigated?', 'The obstructed airflow and actual thermal readings under the workload', 'Only the printer queue name', 'Disable shutdown protection permanently', 'Environmental evidence and safe corrective action should guide the response.',
 ['Draw airflow and shared power dependencies for a small rack.','Compare load/runtime requirements with a fictional UPS specification.','Identify approved handling and disposal references for a battery and toner.'])

add('core2-4.6','privacy-license-evidence','Privacy, licensing, incident records and evidence custody',
 'Support work often exposes information the technician does not need to read or share. Minimize access, preserve confidentiality and use the approved escalation path when prohibited or regulated material is discovered. Applicable obligations depend on the organization, jurisdiction, contracts and data category; a technical support guide is not a substitute for authorized legal/privacy decisions. Incident documentation should preserve who handled what, when and why, with integrity and custody measures appropriate to the investigation. Volatile data can disappear on shutdown, but collection and retention choices require the response plan and qualified authority. Licensing also has scope: personal-use, corporate-use, subscription, perpetual and open-source terms differ, and a product being downloadable does not establish permitted use. An NDA or mutual NDA addresses confidentiality obligations under its terms, not automatic authorization to access every system. Verify data retention, disposal and external-sharing requirements before destructive or publishing actions.',
 [('Access/need to know','Technical capability does not establish authorized purpose.'),('Custody/integrity','Handling records and evidence consistency are separate but complementary.'),('License/distribution','Availability of software does not define usage rights.'),('Retention/deletion','Resolve applicable obligations through the authorized process.')],['Authorized support scope','Data and evidence classification','Controlled handling','Documented escalation/disposition'],
 'A support screenshot includes a customer identifier that is unnecessary for the external question. What should happen before sharing?', 'Apply approved redaction and authorization procedures', 'Post it publicly because the issue is urgent', 'Only rename the image file', 'Minimize disclosure and use the correct authority for external transmission.',
 'A tool is free for personal use but the technician wants to deploy it commercially. What must be checked?', 'The actual license and organizational approval for that use', 'Assume free download means unrestricted corporate use', 'Assume a short filename removes license obligations', 'Cost and permission are different questions.',
 ['Create a fictional evidence-handling record without real customer data.','Compare three license scopes using approved reference terms.','Write an escalation path for a conflict between retention and a deletion request.'])

add('core2-4.7','professional-support','Communication, difficult situations and confidential workspaces',
 'Professional support is part of the technical outcome. Arrive with appropriate identification and attire for the environment, communicate delays early and avoid distractions. Listen without interrupting, clarify ambiguous symptoms with open questions and restate the problem to verify understanding. Use language the user can act on instead of unexplained acronyms or blame. A frustrated user’s report can still contain useful evidence; separate empathy and expectation setting from unsupported technical agreement. Explain the current state, options, likely impact and next update time without promising an unverified fix. Be culturally respectful and use appropriate names/titles. Protect private material visible on screens, desks or printers and do not browse unrelated content. Document the authorized work and follow up to confirm both the original function and user acceptance. Confidence should come from clear process and evidence, not certainty beyond what the investigation supports.',
 [('Listen/clarify','Confirm the symptom before arguing about a proposed cause.'),('Evidence/confidence','Clear process is better than unsupported certainty.'),('Expectation/update','Communicate scope, timing and changes in the plan.'),('Privacy/professionalism','The workspace may expose material outside the support need.')],['Listen and restate','Set scope and expectations','Explain evidence and options','Verify resolution and acceptance'],
 'A repair is taking longer than the original estimate. What should the technician do?', 'Provide a clear update, revised expectations and the next planned checkpoint', 'Avoid contact until the issue disappears', 'Blame the customer without evidence', 'Timely factual updates preserve trust and enable business planning.',
 'A confidential document is visible while troubleshooting an unrelated display setting. What is the appropriate behavior?', 'Limit attention and handling to the authorized task and protect the user’s privacy', 'Read and copy it because the screen is accessible', 'Discuss it with unrelated staff', 'Access during support does not create an unlimited purpose to inspect content.',
 ['Rewrite a jargon-heavy support update in plain language.','Practice restating an ambiguous symptom without blaming the user.','Create a verification and follow-up note.'])

add('core2-4.9','remote-access-paths','Remote desktop, shells, tunnels and management authority',
 'Choose remote access from the support function and its authorization requirements. RDP, VNC and supported screen-sharing products deliver interactive desktop views with different security and deployment models. SSH provides an encrypted remote shell and related capabilities, not the same user experience as a full desktop. A VPN creates a network path under a defined authentication and routing design; it does not automatically grant application roles. RMM platforms coordinate monitoring and management but can have broad authority and therefore require careful access control, audit and session hygiene. WinRM supports Windows remote management, while SPICE is associated with supported virtual-desktop/display environments. Videoconferencing, file transfer and desktop management features are distinct permissions even when one product bundles them. Obtain appropriate user consent, verify the intended target and operator identity, protect credentials and recordings, and close temporary sessions/access after the task. An internet-facing remote service needs an explicitly approved security design rather than convenience-based broad exposure.',
 [('Desktop/shell/tunnel','Interactive display, command environment and network path are different functions.'),('RMM/WinRM','Management mechanisms can operate with broad unattended authority.'),('Session consent/authorization','User presence does not replace organizational scope and operator control.'),('Connection/role','Reaching a host does not grant every resource permission.')],['Authorized operator and target','Protected connection','Scoped desktop/shell/management action','Session closure and audit'],
 'A VPN connects but a user cannot access a restricted application. What should be examined?', 'The destination path and the user’s application/resource authorization separately', 'Assume tunnel status grants every application role', 'Disable all access policies permanently', 'Connectivity and authorization are different gates.',
 'A support task is finished but an elevated remote session remains open. What should happen?', 'Terminate the session and handle temporary access according to policy', 'Leave it open indefinitely for convenience', 'Share its token in a public channel', 'Session lifecycle and authority should remain bounded to the authorized work.',
 ['Draw a remote desktop, shell and VPN path separately.','Mark consent, authentication, authorization and audit points.','Create a session-closure verification checklist.'])

